<script setup>
import AppShell from'../Layouts/AppShell.vue';import StateCard from'../Components/StateCard.vue';import{Head,router}from'@inertiajs/vue3';import{computed,onBeforeUnmount,onMounted,ref}from'vue';
const props=defineProps({subject:Object,photos:Array,event:Object,partialError:Boolean,consent:Object,deletion:Object});const rejecting=ref(null),timer=ref();
const reviewCount=computed(()=>props.photos.filter(p=>p.review_state==='unreviewed').length);const visible=computed(()=>props.photos.filter(p=>p.review_state!=='unreviewed'));
function reject(photo){if(!confirm('Mark this photograph as an incorrect match? It will disappear from My Photos.'))return;rejecting.value=photo.match_id;router.post(`/face-matches/${photo.match_id}/reject`,{}, {preserveScroll:true,onSuccess:()=>router.reload({only:['photos','partialError']}),onFinish:()=>rejecting.value=null})}
onMounted(()=>{timer.value=setInterval(()=>{if(['queued','processing'].includes(props.subject.state)||['queued','processing'].includes(props.deletion?.state))router.reload({only:['subject','photos','partialError','deletion'],preserveScroll:true})},2500)});onBeforeUnmount(()=>clearInterval(timer.value));
</script>
<template><AppShell><Head title="My Photos"/><div class="mx-auto max-w-6xl"><p class="eyebrow">Private discovery</p><h1 class="mt-2 font-display text-3xl font-bold">My Photos · {{event.name}}</h1><p class="mt-3 max-w-2xl text-sm leading-6 text-black/50">Matches are suggestions, not proof of identity. Every photograph is re-authorized against your current event, gallery, folder, media and download permissions.</p><StateCard v-if="deletion?.state==='completed'||consent?.state==='deleted'" class="mt-8" title="Biometric data deleted" message="Your event-specific personalized results are no longer available." tone="success"/><StateCard v-else-if="subject.deletion_state==='completed'&&subject.state==='cancelled'" class="mt-8" title="Search cancelled" message="The temporary selfie was deleted and no results were released."/><StateCard v-else-if="['queued','processing'].includes(subject.state)" class="mt-8" title="Finding your moments" message="Your private search is processing. This page refreshes automatically."/><StateCard v-else-if="subject.state==='failed'" class="mt-8" title="Search failed safely" message="The temporary selfie was deleted. Return to the event to try again." tone="error"/><StateCard v-else-if="subject.outcome==='no_face'" class="mt-8" title="No face detected" message="Try another selfie with one clearly visible face." tone="error"/><StateCard v-else-if="subject.outcome==='multiple_faces'" class="mt-8" title="Multiple faces detected" message="Please submit a selfie containing only you." tone="error"/><template v-else><div v-if="partialError" class="mt-6 border-l-4 border-gold bg-gold/10 p-4 text-sm">Some stored candidates are no longer accessible and were safely omitted.</div><div v-if="reviewCount" class="mt-6 border-l-4 border-indigo bg-indigo/5 p-4 text-sm">{{reviewCount}} candidate photo<span v-if="reviewCount!==1">s</span> await authorized manual review and are not shown yet.</div><StateCard v-if="!visible.length" class="mt-8" title="No authorized matches" message="No above-threshold photographs are currently available within your permissions."/><div v-else class="photo-grid mt-8 grid grid-cols-2 gap-1 md:grid-cols-3 lg:grid-cols-4"><figure v-for="p in visible" :key="p.match_id" class="photo-tile group relative aspect-[4/3] overflow-hidden bg-black/10"><img :src="p.url" alt="Event photograph" class="h-full w-full object-cover"><div class="absolute inset-x-0 bottom-0 flex items-center justify-between gap-2 bg-gradient-to-t from-black/80 to-transparent p-2 pt-8"><a v-if="p.download_url" :href="p.download_url" class="bg-white px-3 py-2 text-xs font-semibold text-ink">Download</a><span v-else class="px-2 text-xs text-white/65">Download restricted</span><button class="bg-black/75 px-3 py-2 text-xs font-semibold text-white" :disabled="rejecting===p.match_id" @click="reject(p)">{{rejecting===p.match_id?'Removing…':'This is not me'}}</button></div></figure></div></template></div></AppShell></template>
